const item = $input.first().json;
const config = { ...item.config, visitorOtpCancelUrl: 'https://visitor.example.test/api/automation/otp/cancel' };
return (function routeMetaMessages(event, config) {
  if (event?.verified !== true) throw new Error('A verified Meta event is required before routing.');
  const productionUrl = value => {
    // URL is not exposed in every n8n Code sandbox. Accept ordinary n8n HTTPS
    // production URLs without relying on imports, environment access or Node globals.
    const match = typeof value==='string' && /^https:\/\/([a-z\d.-]+(?::\d{1,5})?)(\/webhook\/[a-z\d_/-]+)$/i.exec(value);
    if (!match || value.length>2048 || /\s/.test(value) || match[1].toLowerCase()==='your-n8n-host' ||
        match[2].replace(/\/$/,'').endsWith('/srv-shared-whatsapp-inbound')) {
      throw new Error('Use distinct HTTPS production webhook URLs, never the shared router or test URL.');
    }
    return value.replace(/\/$/,'');
  };
  const visitorUrl = productionUrl(config?.visitorWebhookUrl), csatUrl = productionUrl(config?.csatWebhookUrl);
  if (visitorUrl === csatUrl) throw new Error('Visitor and CSAT destinations must be different.');
  if (typeof config?.phoneNumberId !== 'string' || !/^\d+$/.test(config.phoneNumberId)) throw new Error('Configure the shared Meta phone-number ID.');
  const jobs = [], seen = new Set(), envelope = event.envelope;
  for (const entry of envelope.entry) for (const change of Array.isArray(entry?.changes)?entry.changes:[]) {
    const value = change?.value;
    if (change?.field !== 'messages' || value?.metadata?.phone_number_id !== config.phoneNumberId) continue;
    for (const message of Array.isArray(value.messages)?value.messages:[]) {
      if (typeof message?.id !== 'string' || !message.id || typeof message.from !== 'string' || !/^\d+$/.test(message.from)) continue;
      const key = message.from+':'+message.id;
      if (seen.has(key)) continue;
      seen.add(key);
      const payloads = [message.button?.payload, message.interactive?.button_reply?.id];
      if (payloads.includes('DID_NOT_REQUEST_CODE')) {
        // Auth-template controls belong to the OTP handler. Ignore incomplete
        // controls instead of forwarding them to a conversation workflow.
        const messageId = message.context?.id;
        const targetUrl = config?.visitorOtpCancelUrl;
        if (typeof messageId === 'string' && /^wamid\.[a-z\d+/_=-]{1,294}$/i.test(messageId) &&
            /^[1-9]\d{6,14}$/.test(message.from) && typeof targetUrl === 'string' &&
            /^https:\/\/[a-z\d.-]+\/api\/automation\/otp\/cancel$/i.test(targetUrl)) {
          // The existing visitor forwarding node uses Reception app secret.
          jobs.push({ route:'visitor', targetUrl, body:{ phone:message.from, messageId } });
        }
        continue;
      }
      // The entire rms| namespace is isolated, including malformed visitor payloads.
      // The visitor app validates the action signature, intended host phone, expiry and final state.
      if (payloads.some(payload=>typeof payload==='string' && payload.startsWith('rms|'))) {
        jobs.push({ route:'visitor', targetUrl:visitorUrl, body:{ message } });
      } else {
        // The supplied CSAT router reads messages[0]. Split batches so each message keeps its
        // original ID, timestamp, context and metadata, without leaking visitor-only messages.
        const isolatedValue = { ...value, messages:[message] };
        if (Array.isArray(value.contacts)) isolatedValue.contacts = value.contacts.filter(contact=>contact?.wa_id===message.from);
        jobs.push({ route:'csat', targetUrl:csatUrl, body:{ ...envelope, entry:[{ ...entry, changes:[{ ...change, value:isolatedValue }] }] } });
      }
    }
  }
  // Status receipts have no message to process. Never treat them as approvals or CSAT text.
  return jobs.length?jobs:[{ route:'ignore' }];
})(item,config).map(json=>({json,pairedItem:{item:0}}));
